package com.mediaflow.platform.dto;

import lombok.Data;

/**
 * Fixed response envelope: {@code {"code": <int>, "message": <string>, "data": <object|array|null>}}.
 * Business outcomes are conveyed through {@code code}; the HTTP status stays 200 for
 * every controller-produced response.
 */
@Data
public class ApiResponse<T> {

    private int code;
    private String message;
    private T data;

    public ApiResponse() {
    }

    public ApiResponse(int code, String message, T data) {
        this.code = code;
        this.message = message;
        this.data = data;
    }

    /** Success envelope with the default {@code "success"} message. */
    public static <T> ApiResponse<T> success(T data) {
        return new ApiResponse<>(200, "success", data);
    }

    /** Success envelope with a custom message (e.g. task submission / template deletion). */
    public static <T> ApiResponse<T> success(String message, T data) {
        return new ApiResponse<>(200, message, data);
    }

    /** Error envelope carrying the business code and message, with null data. */
    public static <T> ApiResponse<T> error(int code, String message) {
        return new ApiResponse<>(code, message, null);
    }
}

